//! The languages the platform's own text is shipped in, and which one a
//! recipient's locale or a reader's language tag reads.
//!
//! The translated resources live in `locales/<tag>/`, generated by
//! `ianua-translate write-fluent`. English is the source and every
//! message's fallback.

mod wording;

use ianua_domain::types::Locale;

pub use self::wording::FluentRefusalWording;

/// A language the platform's mail and pages are shipped in.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Language {
    /// English, the source of every message.
    English,
    /// Resources selected by the `de` language subtag.
    German,
    /// Resources selected by the `es` language subtag.
    Spanish,
    /// Resources selected by the `fr` language subtag.
    French,
    /// Resources selected by the `ja` language subtag.
    Japanese,
    /// Resources selected by the `ka` language subtag.
    Georgian,
    /// Resources selected by the `uk` language subtag.
    Ukrainian,
    /// Resources for `zh`, `zh-Hans`, `zh-CN` and `zh-SG` tags.
    SimplifiedChinese,
}

impl Language {
    /// Every shipped language.
    pub const ALL: [Self; 8] = [
        Self::English,
        Self::German,
        Self::Spanish,
        Self::French,
        Self::Japanese,
        Self::Georgian,
        Self::Ukrainian,
        Self::SimplifiedChinese,
    ];

    /// The language `locale` reads: the one of its language subtag, or
    /// English when the platform does not ship it. Chinese of Hong Kong
    /// and Taiwan is written in Traditional characters, which are not
    /// shipped, so it reads English too.
    #[must_use]
    pub fn of(locale: &Locale) -> Self {
        Self::of_tag(locale.as_str()).unwrap_or(Self::English)
    }

    /// The shipped language a BCP 47 tag such as `de-AT`, `ja` or
    /// `zh-Hans-CN` names, matched without regard to case. None for a
    /// language the platform does not ship, Traditional Chinese among them.
    #[must_use]
    pub fn of_tag(tag: &str) -> Option<Self> {
        let lowered = tag.trim().to_ascii_lowercase();
        let mut subtags = lowered.split(['-', '_']);
        let language = subtags.next()?;
        let next = subtags.next().unwrap_or("");
        match (language, next) {
            ("en", _) => Some(Self::English),
            ("de", _) => Some(Self::German),
            ("es", _) => Some(Self::Spanish),
            ("fr", _) => Some(Self::French),
            ("ja", _) => Some(Self::Japanese),
            ("ka", _) => Some(Self::Georgian),
            ("uk", _) => Some(Self::Ukrainian),
            ("zh", "" | "hans" | "cn" | "sg") => Some(Self::SimplifiedChinese),
            _ => None,
        }
    }

    /// The first shipped language among `tags`, most wanted first, or
    /// English when none is shipped or English comes first.
    #[must_use]
    pub fn first_shipped(tags: &[String]) -> Self {
        tags.iter()
            .find_map(|tag| Self::of_tag(tag))
            .unwrap_or(Self::English)
    }

    /// The language a recipient with `locale` reads, English when none is known.
    #[must_use]
    pub fn of_recipient(locale: Option<&Locale>) -> Self {
        locale.map_or(Self::English, Self::of)
    }

    /// The BCP 47 tag its resource folder is named after.
    #[must_use]
    pub fn tag(self) -> &'static str {
        match self {
            Self::English => "en",
            Self::German => "de",
            Self::Spanish => "es",
            Self::French => "fr",
            Self::Japanese => "ja",
            Self::Georgian => "ka",
            Self::Ukrainian => "uk",
            Self::SimplifiedChinese => "zh-Hans",
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn of(tag: &str) -> Language {
        Language::of(&Locale::new(tag).unwrap())
    }

    /// Every regional variant of a shipped language reads that language.
    #[test]
    fn regional_variants_read_their_language() {
        assert_eq!(of("de-AT"), Language::German);
        assert_eq!(of("fr-CA"), Language::French);
        assert_eq!(of("uk-UA"), Language::Ukrainian);
        assert_eq!(of("ka-GE"), Language::Georgian);
    }

    /// Simplified Chinese is chosen only where it is the written standard.
    #[test]
    fn traditional_chinese_falls_back_to_english() {
        assert_eq!(of("zh-CN"), Language::SimplifiedChinese);
        assert_eq!(of("zh-TW"), Language::English);
    }

    /// A language the platform does not ship, or no locale, reads English.
    #[test]
    fn unshipped_or_unknown_reads_english() {
        assert_eq!(of("en-GB"), Language::English);
        assert_eq!(of("it-IT"), Language::English);
        assert_eq!(Language::of_recipient(None), Language::English);
    }

    /// Browser tags of any case and length name their language; others name none.
    #[test]
    fn browser_tags_name_their_language() {
        assert_eq!(Language::of_tag("DE"), Some(Language::German));
        assert_eq!(
            Language::of_tag("zh-Hans-CN"),
            Some(Language::SimplifiedChinese)
        );
        assert_eq!(Language::of_tag("zh-Hant"), None);
        assert_eq!(Language::of_tag("*"), None);
    }
}
